import type { ConfidenceBand, ReadingField } from '@domain/types.ts';
import type { ParsedReading } from '@domain/ocr-parse.ts';
import { config } from '@/app/config';
import { logger } from '@/lib/logger';
import type { DashboardReadRequest, DashboardReadResult, DashboardReadingProvider } from './types';

/**
 * Remote adapter for `services/dashboard-ocr` (RapidOCR + OpenCV).
 *
 * This is the one adapter in this directory that sends the photograph
 * somewhere: everything else in `docs/OCR.md` is written around the promise
 * that a dashboard photo never leaves the device. That promise is worth
 * keeping by default — `tesseractDashboardProvider` remains the default
 * provider — but it is a real accuracy trade-off, not just a nicety. Tested
 * against six real photographs of this fleet's cluster, the on-device seven-
 * segment fusion read both fields exactly right on two; this service, on all
 * six — including two shot sideways and one with a glare reflection across
 * the display, cases the on-device reader could not recover from. An
 * organisation opts into that trade explicitly, by setting
 * `VITE_OCR_PROVIDER=remote`, never by default.
 *
 * The engine itself already separates recognition from parsing (see
 * `ocr-parse.ts`), but this service does its own field-specific extraction —
 * it was built for exactly this cluster's ODO/AFE layout, not a generic
 * dashboard — so its response is mapped directly to `ParsedReading`s here
 * rather than routed back through the generic word parser.
 */

const ENGINE_VERSION = 'rapidocr-bus-dash-1';
// Measured against the deployed service: ~24s on a cold start, ~17s warm —
// the four-rotation OCR pass is genuinely CPU-heavy on a single vCPU, not
// dominated by model-load time. 45s leaves real margin above both.
const REQUEST_TIMEOUT_MS = 45_000;

type RemoteConfidence = 'high' | 'medium' | 'low' | 'none';

export interface RemoteReadResponse {
  odo: number | null;
  afe: number | null;
  confidence: { odo: RemoteConfidence; afe: RemoteConfidence };
  needs_review: boolean;
  rotation: number;
  notes: string[];
}

const CONFIDENCE: Record<Exclude<RemoteConfidence, 'none'>, { value: number; band: ConfidenceBand }> = {
  high: { value: 0.95, band: 'HIGH' },
  medium: { value: 0.7, band: 'MEDIUM' },
  low: { value: 0.4, band: 'LOW' },
};

const WANTED_FIELDS: ReadingField[] = ['ODOMETER', 'RANGE_KM'];

export function toReadings(
  data: RemoteReadResponse,
): { readings: ParsedReading[]; missing: ReadingField[] } {
  const readings: ParsedReading[] = [];
  const fields: Array<{ field: ReadingField; value: number | null; confidence: RemoteConfidence }> = [
    { field: 'ODOMETER', value: data.odo, confidence: data.confidence.odo },
    { field: 'RANGE_KM', value: data.afe, confidence: data.confidence.afe },
  ];
  for (const { field, value, confidence } of fields) {
    if (value == null || confidence === 'none') continue;
    const { value: numericConfidence, band } = CONFIDENCE[confidence];
    // The service returns a final number, not the source token it read the
    // number from — unlike the word-level parsers, there is no separate OCR
    // text to show next to it, so the value itself is the closest thing.
    readings.push({ field, value, confidence: numericConfidence, band, sourceText: String(value) });
  }
  const found = new Set(readings.map((r) => r.field));
  return { readings, missing: WANTED_FIELDS.filter((field) => !found.has(field)) };
}

function failure(
  engine: string,
  engineVersion: string,
  startedAt: number,
  raw: unknown,
): DashboardReadResult {
  return {
    parsed: { readings: [], missing: WANTED_FIELDS, normalisedText: '' },
    raw,
    engine,
    engineVersion,
    durationMs: Math.round(performance.now() - startedAt),
    status: 'FAILED',
  };
}

class RemoteDashboardProvider implements DashboardReadingProvider {
  readonly name = 'remote-python';
  readonly version = ENGINE_VERSION;

  // There is no local model to warm up — the remote service loads its own
  // model lazily on its first request, which shows up as ordinary request
  // latency rather than something this provider needs to orchestrate.
  isLoaded(): boolean {
    return true;
  }

  async load(onProgress?: (fraction: number) => void): Promise<void> {
    onProgress?.(1);
  }

  async read(request: DashboardReadRequest): Promise<DashboardReadResult> {
    const started = performance.now();
    const endpoint = config.ocr.remoteEndpoint;
    if (!endpoint) {
      logger.error('Remote OCR provider selected but VITE_OCR_REMOTE_ENDPOINT is not set');
      return failure(this.name, this.version, started, { error: 'not_configured' });
    }

    request.onProgress?.(0.1);
    const form = new FormData();
    form.append('image', request.image, 'dashboard.jpg');
    if (request.hints?.previousOdometerKm != null) {
      form.append('prev_odo', String(request.hints.previousOdometerKm));
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    let response: Response;
    try {
      response = await fetch(endpoint, {
        method: 'POST',
        headers: config.ocr.remoteApiKey ? { 'X-Api-Key': config.ocr.remoteApiKey } : {},
        body: form,
        signal: controller.signal,
      });
    } catch (error) {
      // A cold start on a scale-to-zero host can take several seconds; that
      // is a slow success, not this catch block. This is network failure or
      // the 25 s timeout above, both genuinely unreachable.
      logger.warn('Remote OCR request failed', { error });
      return failure(this.name, this.version, started, {
        error: error instanceof Error ? error.message : String(error),
      });
    } finally {
      clearTimeout(timeout);
    }

    request.onProgress?.(0.8);
    if (!response.ok) {
      const body = await response.text().catch(() => '');
      logger.warn('Remote OCR returned an error response', { status: response.status, body });
      return failure(this.name, this.version, started, { status: response.status, body });
    }

    // A successful HTTP status is not a guarantee of a parseable, well-shaped
    // body — an intermediary can still return 200 with something unexpected.
    // This must return a FAILED result rather than throw: `useDashboardCapture`
    // only produces a draft in its own try block's happy path, so an exception
    // escaping here means no draft ever gets set while the flow still moves on
    // to the review screen regardless, which renders nothing at all.
    try {
      const data = (await response.json()) as RemoteReadResponse;
      request.onProgress?.(1);
      const { readings, missing } = toReadings(data);
      const durationMs = Math.round(performance.now() - started);

      logger.debug('Remote dashboard OCR complete', {
        readings: readings.map(({ field, value }) => ({ field, value })),
        missing,
        needsReview: data.needs_review,
        rotation: data.rotation,
        notes: data.notes,
        durationMs,
      });

      return {
        parsed: { readings, missing, normalisedText: data.notes.join(' | ') },
        raw: data,
        engine: this.name,
        engineVersion: this.version,
        durationMs,
        status: readings.length === 0 ? 'FAILED' : missing.length > 0 ? 'PARTIAL' : 'SUCCEEDED',
      };
    } catch (error) {
      logger.warn('Remote OCR response could not be parsed', { error });
      return failure(this.name, this.version, started, {
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async dispose(): Promise<void> {
    // No connection or worker is held open between reads.
  }
}

export const remoteDashboardProvider: DashboardReadingProvider = new RemoteDashboardProvider();
