import { useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Camera, ImagePlus, Loader2 } from 'lucide-react';
import type { CaptureKind } from '@domain/types.ts';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/controls';
import { ErrorState } from '@/components/feedback/states';
import { useCamera } from './useCamera';
import { CameraView, DashboardGuideOverlay } from './CameraView';

/**
 * Dashboard photography.
 *
 * Rear camera, no exposure bias — pushing exposure up would blow out an
 * instrument cluster that is already self-illuminated, which is the opposite
 * of what is needed for the face scanner.
 *
 * The framing rectangle is guidance rather than a crop: cropping to it would
 * throw away context that helps when a reading is later disputed, and managers
 * do not aim as precisely as designers imagine.
 *
 * The instant the shutter fires, the live feed is replaced by the frozen
 * photo just taken, with a processing overlay on top of it — not a small
 * status card wedged under a camera that is still visibly streaming, which
 * reads as "did anything happen?" during a reading that can take real
 * seconds (a remote OCR provider's network round trip is not instant).
 * Showing the actual photo also lets a supervisor confirm the shot was framed
 * correctly while it works, rather than staring at unrelated live video.
 */
export function DashboardScanner({
  kind,
  processing,
  progress,
  error,
  onCapture,
  onManualEntry,
}: {
  kind: CaptureKind;
  processing: boolean;
  progress: number;
  error: unknown;
  onCapture: (blob: Blob) => void | Promise<void>;
  onManualEntry: () => void;
}) {
  const { t } = useTranslation();
  const camera = useCamera({ facing: 'environment' });
  const [capturing, setCapturing] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const fileInput = useRef<HTMLInputElement>(null);
  const rootRef = useRef<HTMLDivElement>(null);

  // The step-so-far summary and the step header above this component (rendered
  // by the trip flow, not here) routinely push the camera and the shutter
  // button below the fold on a phone. This is the step where the action is —
  // land on it already scrolled to, not stacked under text to read past.
  useEffect(() => {
    rootRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }, []);

  // Revoke whichever preview URL is current when a new one replaces it, and
  // on unmount (the flow moves on to the review screen once processing ends).
  useEffect(() => () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
  }, [previewUrl]);

  const runCapture = async (blob: Blob) => {
    setPreviewUrl(URL.createObjectURL(blob));
    try {
      await onCapture(blob);
    } finally {
      // Only reached if the caller didn't navigate away (e.g. capture failed
      // before producing a draft) — drop the frozen frame so the live camera
      // reappears instead of leaving a stale photo on screen.
      setPreviewUrl(null);
    }
  };

  // Covers the brief window between tapping the shutter and having a frame to
  // show as the frozen photo, before `previewUrl` takes over as the signal.
  const take = async () => {
    setCapturing(true);
    try {
      const blob = await camera.capture();
      if (blob) await runCapture(blob);
    } finally {
      setCapturing(false);
    }
  };

  const choosePhoto = async (file: File | undefined) => {
    if (!file) return;
    setCapturing(true);
    try {
      await runCapture(file);
    } finally {
      setCapturing(false);
      // Selecting the same photograph again must still fire a change event.
      if (fileInput.current) fileInput.current.value = '';
    }
  };

  const busy = capturing || processing;

  return (
    <div ref={rootRef} className="space-y-4">
      <div>
        <h2 className="text-base font-bold">
          {kind === 'TRIP_END' ? t('capture.endTitle') : t('capture.startTitle')}
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">{t('capture.hint')}</p>
      </div>

      {error != null && <ErrorState error={error} compact />}

      {previewUrl ? (
        <div className="space-y-3">
          <div className="relative overflow-hidden rounded-xl bg-black">
            <img
              src={previewUrl}
              alt={t('capture.title')}
              className="aspect-[3/4] w-full object-cover sm:aspect-[4/3]"
            />
            <div className="absolute inset-0 grid place-items-center bg-black/60 text-white">
              <div className="flex flex-col items-center gap-2 px-6 text-center">
                <Loader2 className="size-7 animate-spin" aria-hidden />
                <p className="text-sm font-medium">
                  {progress < 0.2 ? t('capture.compressing') : t('capture.processing')}
                </p>
              </div>
            </div>
          </div>
          <Progress value={Math.round(progress * 100)} />
        </div>
      ) : (
        <CameraView
          camera={camera}
          onFallback={onManualEntry}
          fallbackLabel={t('actions.enterManually')}
          overlay={<DashboardGuideOverlay hint={t('capture.instruction')} />}
        />
      )}

      {/* Hidden once there's a photo to process — at that point the overlay
          above is the only thing happening, and three greyed-out buttons
          under it would just be noise while waiting on OCR. */}
      {!previewUrl && (
        <div className="space-y-2">
          <Button
            size="lg"
            block
            onClick={() => void take()}
            disabled={camera.status !== 'streaming' || busy}
            loading={busy}
          >
            <Camera className="size-5" aria-hidden />
            {t('actions.takePhoto')}
          </Button>
          <input
            ref={fileInput}
            className="sr-only"
            type="file"
            accept="image/jpeg,image/png,image/webp"
            onChange={(event) => void choosePhoto(event.target.files?.[0])}
            disabled={busy}
          />
          <Button
            variant="outline"
            size="lg"
            block
            onClick={() => fileInput.current?.click()}
            disabled={busy}
          >
            <ImagePlus className="size-5" aria-hidden />
            {t('actions.choosePhoto')}
          </Button>
          <Button variant="ghost" size="lg" block onClick={onManualEntry} disabled={busy}>
            {t('actions.enterManually')}
          </Button>
        </div>
      )}
    </div>
  );
}
